<?php require_once 'config/config.php';$title='Login';$error='';$secs=0;if(user()){header('Location:'.(user()['role']==='admin'?'admin/index.php':'dashboard.php'));exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$p=$_POST['password']??'';$s=db()->prepare("SELECT * FROM users WHERE email=?");$s->execute([$email]);$u=$s->fetch();if(!$u)$error='Invalid email or password.';elseif($u['locked_until']&&strtotime($u['locked_until'])>time()){$secs=strtotime($u['locked_until'])-time();$error='Your account is temporarily locked.';}else{if($u['locked_until'])db()->prepare("UPDATE users SET failed_login_attempts=0,locked_until=NULL WHERE id=?")->execute([$u['id']]);if(password_verify($p,$u['password'])){db()->prepare("UPDATE users SET failed_login_attempts=0,locked_until=NULL,last_login=NOW() WHERE id=?")->execute([$u['id']]);session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'first_name'=>$u['first_name'],'last_name'=>$u['last_name'],'email'=>$u['email'],'role'=>$u['role']];activity((int)$u['id'],'login','Successful login');header('Location:'.($u['role']==='admin'?'admin/index.php':'dashboard.php'));exit;}else{$a=(int)$u['failed_login_attempts']+1;if($a>=3){$until=date('Y-m-d H:i:s',time()+180);db()->prepare("UPDATE users SET failed_login_attempts=3,locked_until=?,last_failed_login=NOW() WHERE id=?")->execute([$until,$u['id']]);$secs=180;$error='Three failed attempts. Your account is locked for 3 minutes.';}else{db()->prepare("UPDATE users SET failed_login_attempts=?,last_failed_login=NOW() WHERE id=?")->execute([$a,$u['id']]);$error="Invalid email or password. Attempt $a of 3.";}}}}require 'includes/header.php';?><div class="auth-wrap"><div class="container"><div class="card auth-card"><div class="card-body p-4 p-md-5"><span class="eyebrow">Welcome back</span><h1 class="fw-bold">Log in</h1><?php if($error):?><div class="alert alert-danger"><?=e($error)?><?php if($secs):?><span class="d-block fw-bold" data-lock-seconds="<?=$secs?>"></span><?php endif;?></div><?php endif;?><form method="post" novalidate><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Password</label><input class="form-control mb-4" type="password" name="password" required><button class="btn btn-primary w-100 btn-lg">Log in</button></form><p class="mt-3">New here? <button class="btn btn-link p-0" data-bs-toggle="modal" data-bs-target="#joinModal">Create an account</button></p></div></div></div></div><?php require 'includes/footer.php';?>